    if cursor.rowcount != 1:
        raise ValueError("insufficient funds")
    cursor = connection.execute("UPDATE accounts SET balance=balance+? WHERE id=?", (amount, target))
    if cursor.rowcount != 1:
        raise ValueError("unknown target account")
    connection.execute("INSERT INTO ledger VALUES (?, ?, ?)", (source, target, amount))
