import os, sys
sys.path.insert(0, os.getcwd())
import sqlite3
from src.repository import initialize, balance
from src.service import transfer
from src.events import Recorder


def fresh(isolation=""):
    c = sqlite3.connect(":memory:", isolation_level=isolation)
    if isolation is None:
        c.execute("BEGIN")
    initialize(c)
    c.executemany("INSERT INTO accounts VALUES (?, ?)", [("a", 100), ("b", 20)])
    c.commit()
    return c


def state(c):
    return (balance(c, "a"), balance(c, "b"),
            c.execute("SELECT * FROM ledger").fetchall())


class Flaky:
    """Proxy that fails the Nth execute call or the commit."""
    def __init__(self, conn, fail_execute=None, fail_commit=False):
        self.conn, self.n, self.fail_execute, self.fail_commit = conn, 0, fail_execute, fail_commit
    @property
    def in_transaction(self):
        return self.conn.in_transaction
    def execute(self, *a):
        self.n += 1
        if self.n == self.fail_execute:
            raise sqlite3.OperationalError("boom")
        return self.conn.execute(*a)
    def commit(self):
        if self.fail_commit:
            raise sqlite3.OperationalError("commit boom")
        self.conn.commit()
    def rollback(self):
        self.conn.rollback()


class BadPublisher:
    def publish(self, event):
        raise RuntimeError("publish failed")


for iso in ("", None, "DEFERRED"):
    # success
    c = fresh(iso); p = Recorder()
    transfer(c, p, "a", "b", 100)
    assert state(c) == (0, 120, [("a", "b", 100)])
    assert p.events == [{"source": "a", "target": "b", "amount": 100}]
    assert not c.in_transaction

    # invalid inputs
    for args in [("a", "a", 1), ("a", "x", 1), ("x", "b", 1), ("a", "b", 0),
                 ("a", "b", -5), ("a", "b", True), ("a", "b", 1.0), ("a", "b", "1"),
                 ("a", "b", 101), ("a", "b", None)]:
        c = fresh(iso); p = Recorder()
        try:
            transfer(c, p, *args)
        except ValueError:
            pass
        else:
            raise AssertionError(args)
        assert state(c) == (100, 20, []), args
        assert p.events == [] and not c.in_transaction, args

    # database failure at each statement and at commit
    for k in range(1, 8):
        c = fresh(iso); p = Recorder(); f = Flaky(c, fail_execute=k)
        try:
            transfer(f, p, "a", "b", 10)
        except sqlite3.OperationalError:
            pass
        else:
            assert f.n < k  # fewer statements than k: success path
            continue
        assert state(c) == (100, 20, []), k
        assert p.events == [] and not c.in_transaction, k
    c = fresh(iso); p = Recorder()
    try:
        transfer(Flaky(c, fail_commit=True), p, "a", "b", 10)
        raise AssertionError("expected commit failure")
    except sqlite3.OperationalError:
        pass
    assert state(c) == (100, 20, []) and p.events == []

    # publication failure keeps committed transfer
    c = fresh(iso)
    try:
        transfer(c, BadPublisher(), "a", "b", 10)
        raise AssertionError("expected publish failure")
    except RuntimeError:
        pass
    c.rollback()
    assert state(c) == (90, 30, [("a", "b", 10)])

print("transfer cases OK")
EOF
